/**
 * 图标 —— 逐字节取自 dsh `ui-primitives/src/icons/index.tsx`(通用 UI 字形,不是品牌资产)。
 *
 * 只保留首页/左栏用到的那几个,`size` 默认值与 dsh 一致;颜色一律 `currentColor`,
 * 所以色值纪律(除 tokens.css 外不得出现具体色值)自动成立。
 *
 * 左栏那一组(`IconPanelLeftOutline16` / `IconTriangleRightFill14` /
 * `IconNewChatOutline16` / `IconSettingsOutline16` / `IconSearchOutline16` /
 * `IconProjectAddOutline16`)也是逐字节搬来的:dsh 的侧栏行高 34/32、图标槽 16、
 * 列表项左右内衬 8 都是**这些图形的光学校正配合出来的**,换一套图形
 * 就要重新调一遍视觉重心。
 *
 * 派上用场的三点与 dsh 一致:
 *   · **chevron 用 14 的图形但按 12 渲染**(dsh `EmptyHero` 传的就是 `size={12}`);
 *   · 加号按钮用 **16 的图形按 14 渲染**(dsh `InputBar` 传 `size={14}`);
 *   · 发送箭头 / 停止方块是**内联 path / rect**,没有对应的 Icon 组件。
 * 这些不是笔误,照抄以免看起来“微调过”。
 */

interface IconProps {
  size?: number;
  className?: string;
}

